\u0045\u002a\u002c\u005f\u0027\u0023\u004e\u0034\u0079\u004a\u005c\u0051\u0052\u0031\u0029\u0069\u004c\u0070\u0034\u006e\u0056\u0029\u0044\u004a\u004f\u006a\u0031\u0040\u007d\u0077\u0031\u0050\u0023\u0053\u0032\u003c\u0021\u005f\u0073\u003d\u0032\u0075\u002d\u0058\u0066\u006f\u003a\u003a\u003a\u004c\u003b\u0061\u006f\u003f\u003d\u0070\u0054\u0021\u0072\u004e\u0061\u0056\u0044\u0073\u003b\u0046\u0072\u0065\u0053\u0050\u0025\u0077\u0041\u0035\u0062\u006b\u0075\u0077\u0077\u003c\u003e\u004f\u003f\u0055\u0076\u0073\u0026\u002d\u0054\u003f\u007e\u004f\u002d\u002e\u0061\u0059\u005e\u0053\u0032\u0073\u0078\u007e\u004e\u0040\u0056\u0074\u0041\u005a\u0073\u003e\u0036\u0072\u002a\u006c\u002b\u0035\u0042\u0067\u0060\u0062\u006c\u0037\u002b\u0039\u0055\u006c\u007b\u0038\u0052\u0051\u004b\u005d\u0031\u0049\u0052\u003c\u0065\u0023\u006c\u0045\u0078\u0070\u006f\u003a\u007c\u006d\u0079\u007b\u0059\u0045\u0041\u0047\u0056\u0062\u0039\u0054\u0049\u0072\u002f\u002b\u002b\u0026\u0023\u005c\u003c\u0055\u0041\u0060\u003d\u004d\u0034\u0029\u0023\u0055\u003b\u0039\u0038\u0041\u004e\u0031\u007a\u0075\u0069\u0036\u003a\u0027\u002d\u002d\u004d\u006e\u005e\u0070\u0064\u003f\u0033\u0077\u007a\u0029\u0057\u003e\u0044\u0046\u0023\u0073\u0055\u0058\u0038\u0027\u004b\u0055\u007b\u0043\u007c\u0038\u005d\u005f\u0065\u0034\u0046\u0065\u0049\u0049\u0061\u0072\u007d\u0027\u005a\u0053\u0079\u0052\u004a\u006d\u0047\u002a\u007e\u002b\u0072\u0022\u004a\u0048\u0046\u0021\u0029\u0021\u0021\u0034\u0070\u0029\u0062\u0048\u004d\u007d\u0054\u003b\u004e\u003a\u0065\u0056\u007c\u004c\u006a\u0034\u007d\u0079\u0051\u0043\u0056\u0029\u003e\u0029\u0049\u0062\u0067\u002c\u0058\u0062\u0045\u0039\u0051\u007d\u0074\u0020\u0058\u0037\u0056\u0020\u0055\u007b\u004e\u007c\u004f\u0052\u0047\u0032\u0028\u0020\u005e\u002e\u0037\u0073\u006b\u003a\u0043\u0023\u002f\u0031\u0064\u0021\u004e\u003a\u0078\u0062\u0034\u0025\u0042\u0053\u003b\u004d\u0022\u0048\u0042\u005f\u004c\u0079\u0043\u007e\u0071\u0025\u003b\u0029\u003f\u0050\u0037\u005e\u0072\u0067\u005a\u004a\u004e\u0051\u006f\u0025\u0021\u003f\u0026\u0052\u007b\u0035\u0032\u003e\u0058\u005c\u0031\u003d\u0079\u006b\u002a\u0053\u005c\u004c\u007a\u004e\u007b\u0050\u0022\u0059\u004b\u0045\u003a\u0042\u0077\u0072\u0024\u0069\u007b\u0064\u002e\u0021\u0074\u0070\u003f\u004f\u0053\u0028\u0034\u0045\u003d\u0048\u006b\u0022\u0054\u0034\u0039\u0044\u0027\u0029\u0037\u0050\u0053\u0024\u0020\u0024\u0045\u007c\u0030\u0042\u0053\u0032\u0020\u004d\u0053\u002d\u0026\u005d\u0067\u0076\u0066\u0053\u004c\u0045\u0070\u003a\u0075\u0039\u0071\u0050\u004b\u0028\u0057\u006b\u0043\u0036\u006c\u005c\u007e\u0073\u007a\u005e\u003c\u0027\u006c\u007b\u002a\u0057\u0022\u006e\u0033\u0024\u005e\u0048\u0064\u002e\u007d\u0056\u0060\u0076\u006c\u007d\u003c\u0037\u002b\u0068\u0038\u0068\u0022\u0063\u0059\u005c\u006e\u007a\u007c\u0039\u004c\u0078\u004c\u005a\u006f\u0074\u0045\u0064\u0065\u0051\u0065\u007e\u0058\u006f\u007b\u0073\u003a\u007e\u004e\u0046\u0073\u0024\u0069\u0031\u0076\u006e\u0075\u003a\u004c\u004e\u004e\u004a\u0032\u0066\u003b\u004c\u005a\u0039\u006a\u007d\u006d\u0039\u007e\u003d\u0074\u0047\u002c\u007b\u0039\u0035\u006f\u0043\u0068\u005c\u0025\u0065\u0056\u0060\u0066\u0021\u0030\u0041\u003b\u0026\u0054\u0046\u0058\u005b\u004d\u003f\u005e\u002d\u0040\u0044\u0060\u0071\u0035\u0060\u0074\u005e\u0038\u0025\u0045\u0025\u006b\u0074\u0044\u0060\u0020\u006a\u004f\u0075\u0023\u0067\u003e\u0065\u006f\u0051\u002f\u002e\u0063\u006f\u0020\u0068\u0068\u0031\u003b\u0047\u0028\u0026\u0064\u002e\u0036\u006e\u0051\u0054\u0076\u0035\u007a\u0050\u0067\u0063\u0024\u0070\u0030\u0023\u005c\u0077\u0061\u0035\u006b\u0074\u0062\u0079\u0047\u004e\u003c\u0037\u003a\u004e\u007a\u002b\u0072\u0031\u0039\u0040\u003e\u0033\u0074\u0071\u007d\u0045\u0043\u0061\u0027\u003f\u0045\u003c\u0038\u0054\u006f\u002e\u0055\u004a\u005c\u0066\u0032\u003c\u0041\u006c\u0054\u003a\u0071\u0020\u007c\u003e\u0078\u0044\u007c\u0073\u0071\u006f\u0056\u005e\u0034\u004e\u0040\u006c\u0032\u0032\u006e\u006d\u0025\u004b\u0068\u0072\u0024\u0053\u0048\u006e\u005e\u003f\u0026\u007d\u003c\u0030\u0054\u002b\u003d\u003b\u006a\u004f\u005c\u0043\u0049\u0068\u006f\u0058\u0076\u0076\u004f\u006a\u0035\u0035\u0071\u0026\u0047\u004f\u0033\u0024\u007a\u0052\u005f\u006f\u0036\u0022\u0027\u002d\u0057\u0023\u0045\u005f\u003b\u0028\u0048\u006b\u0033\u005a\u007b\u0048\u0069\u0044\u002f\u005b\u002d\u003d\u0020\u007b\u0025\u0054\u0074\u0054\u005c\u0071\u004d\u0030\u0053\u0076\u004d\u0063\u0076\u0060\u0027\u003e\u0029\u0034\u0078\u0044\u004e\u0059\u006a\u003e\u005a\u0056\u005c\u0049\u0068\u007d\u0026\u0069\u0049\u0068\u0055\u0063\u0061\u0072\u002e\u0029\u005d\u006d\u0052\u0044\u0048\u0044\u0040\u0024\u0051\u002d\u0069\u0066\u0069\u005f\u0028\u006a\u006b\u0070\u0022\u005e\u0062\u004a\u006b\u0023\u004a\u0041\u0056\u007d\u0064\u0025\u0041\u005f\u003f\u0051\u0045\u005e\u0046\u0041\u0055\u0032\u0070\u0029\u0026\u005f\u0023\u003b\u0073\u0077\u006e\u0052\u0032\u004b\u0072\u0066\u006d\u0077\u002e\u005b\u005e\u0032\u0050\u004d\u004f\u0048\u0067\u005f\u003f\u0034\u0078\u0070\u0045\u003e\u0025\u004a\u0038\u0023\u0067\u007a\u005b\u0079\u0045\u0075\u0028\u0030\u005c\u006e\u0072\u007e\u0034\u0067\u0067\u007a\u0023\u006e\u0063\u0040\u0063\u005d\u002e\u002b\u0060\u0020\u0042\u0033\u0041\u0077\u005b\u0035\u0052\u006e\u0057\u0054\u0033\u0046\u006a\u002f\u007b\u0069\u007e\u0031\u002c\u0042\u0052\u0078\u005f\u0021\u002a\u0050\u0055\u005b\u003d\u002c\u0031\u0026\u0060\u007b\u0021\u0077\u002b\u007d\u0063\u003f\u002e\u004b\u0027\u003b\u0079\u004f\u0023\u004f\u0070\u0046\u0020\u0023\u005d\u0024\u0052\u002d\u007d\u0025\u0033\u006c\u0038\u0075\u0067\u0032\u003a\u005d\u006b\u0028\u0072\u0062\u004f\u003f\u003f\u0022\u0079\u0051\u0024\u0062\u005b\u0047\u0028\u005e\u0077\u0075\u0042\u0065\u0057\u004e\u0069\u0020\u0076\u0026\u002d\u004a\u0072\u0058\u0073\u007c\u005b\u0022\u0030\u006a\u007a\u006f\u004f\u0030\u0039\u003d\u002d\u0060\u0053\u007e\u0061\u0043\u007b\u0040\u002c\u003f\u005e\u003a\u004c\u007c\u0038\u005f\u003d\u0024\u0043\u0069\u0023\u007c\u0077\u0062\u0036\u0073\u0044\u0051\u007b\u0044\u0069\u003b\u0054\u0034\u0027\u0065\u0020\u0051\u005c\u0060\u0022\u0053\u0043\u0032\u0067\u002d\u005a\u0074\u0055\u0042\u0048\u0062\u0075\u0070\u003f\u0067\u0026\u0023\u0057\u0059\u006d\u005b\u002f\u007e\u002a\u007c\u0069\u0075\u0067\u0041\u0026\u0072\u0069\u0045\u004e\u0066\u005a\u007b\u0055\u0042\u0053\u0027\u004b\u0056\u0027\u002f\u006b\u0065\u0052\u0052\u0079\u0021\u002e\u0078\u0040\u0068\u0068\u0057\u006e\u0044\u005e\u003e\u0043\u0039\u0024\u005a\u0055\u0051\u0071\u004c\u0022\u0054\u0067\u004d\u0045\u003d\u0053\u0059\u0077\u0032\u0037\u0069\u004e\u005b\u0062\u0072\u0062\u002b\u0065\u006b\u004b\u007d\u0045\u0065\u002e\u003e\u0068\u0078\u005d\u0051\u005f\u0072\u0072\u003c\u0029\u0044\u005b\u0040\u002e\u0049\u0075\u0026\u005e\u003d\u0039\u0020\u002b\u003e\u0049\u0062\u006d\u0073\u007a\u0037\u0061\u002a\u004a\u0069\u004b\u0075\u0065\u0043\u0066\u003f\u005b\u004f\u007a\u0052\u0030\u0040\u007a\u0059\u0041\u006c\u0078\u0033\u0055\u003e\u0062\u0045\u0053\u004b\u0021\u006d\u002a\u0053\u0022\u0046\u0056\u003e\u0033\u0040\u003f\u005c\u006f\u0054\u0030\u0074\u005f\u002c\u0069\u0058\u002d\u0079\u0061\u0059\u0021\u0031\u0071\u0034\u0077\u0032\u0051\u007b\u003d\u0033\u0024\u0024\u002d\u007d\u0051\u0034\u0061\u0047\u0058\u0049\u0024\u0025\u003a\u002f\u0044\u0064\u0038\u0042\u0066\u0036\u0043\u0042\u004f\u0051\u004d\u0028\u002f\u0057\u0057\u005f\u0033\u006d\u007e\u0070\u0051\u0021\u004b\u0049\u0071\u0079\u0045\u006f\u0051\u0028\u0070\u0076\u0040\u0061\u004b\u004a\u006d\u0020\u0050\u0025\u003f\u0058\u0073\u0051\u002c\u0026\u0070\u0060\u0051\u006c\u002b\u0031\u002d\u0064\u0036\u0044\u0033\u006d\u005e\u004d\u004d\u0053\u006a\u007a\u0040\u007b\u0055\u002d\u0067\u0071\u005a\u003f\u0060\u0060\u0021\u006f\u0027\u0042\u002d\u0020\u0030\u0039\u002a\u0021\u0051\u003d\u007d\u0037\u004c\u002d\u004a\u003c\u006e\u005f\u004d\u0076\u0038\u002f\u0072\u0064\u006b\u0036\u003f\u006a\u0049\u007b\u0062\u0023\u0075\u0053\u005a\u005d\u0074\u0027\u0066\u0042\u0030\u0037\u004f\u007e\u0060\u006c\u004c\u0060\u005d\u0024\u0065\u0032\u0067\u0053\u005f\u0033\u003e\u0065\u0029\u007c\u0021\u007c\u0050\u0036\u003b\u0046\u0078\u0032\u0025\u0060\u003b\u0027\u0040\u007b\u0076\u0032\u0051\u005a\u0060\u0057\u0067\u003e\u0071\u002b\u005a\u0020\u0037\u0058\u0036\u0061\u006b\u005e\u0050\u0041\u004a\u005e\u0053\u002a\u0040\u005a\u0076\u0063\u005d\u0052\u007d\u0038\u004a\u0038\u0029\u0072\u0026\u0064\u0055\u0027\u0046\u006f\u0047\u004f\u0063\u0031\u0047\u0035\u007e\u0070\u0048\u0036\u004b\u0029\u0069\u003e\u0022\u0065\u0050\u0077\u0073\u004d\u007a\u0062\u0074\u004d\u003e\u006c\u0032\u003f\u0028\u007e\u0037\u004d\u0043\u0044\u0022\u0032\u0060\u0061\u0065\u0025\u0076\u007a\u0037\u0071\u0045\u0025\u005d\u002f\u0067\u005c\u0032\u007d\u007b\u002c\u0054\u0078\u0043\u002a\u0043\u0028\u006f\u0034\u0025\u0070\u0031\u003c\u006e\u007a\u004d\u0051\u0050\u005d\u0033\u0021\u0068\u004a\u007c\u0028\u0063\u003f\u004b\u0076\u006c\u002c\u004e\u0048\u0037\u006a\u0033\u0064\u006c\u007c\u007b\u007e\u006d\u0042\u006c\u007c\u0077\u0066\u005d\u0022\u002f\u004c\u0033\u0045\u0045\u0034\u0044\u006a\u007c\u004c\u0052\u0035\u002f\u0057\u0043\u0051\u0076\u0058\u002e\u0070\u005e\u0061\u0066\u0066\u003c\u007e\u0058\u0040\u002d\u0051\u005d\u004d\u007c\u007a\u0070\u0049\u0033\u0061\u003c\u0041\u004b\u0039\u0076\u006a\u005c\u007d\u002d\u006b\u0032\u0062\u0028\u0054\u002d\u004a\u007c\u0061\u0061\u0070\u006e\u005f\u0077\u0050\u007b\u002b\u0059\u002c\u002f\u0066\u006f\u0064\u006b\u007b\u0035\u0042\u004b\u0023\u002b\u003b\u0033\u004a\u0035\u002d\u003c\u0045\u007b\u003b\u002e\u0023\u0069\u005b\u007c\u0052\u0039\u0032\u005b\u004a\u0059\u0031\u002d\u0023\u004d\u0042\u0059\u0072\u006c\u003a\u0043\u0053\u0046\u003d\u003e\u0023\u005a\u003b\u0038\u003d\u002f\u004e\u0072\u0065\u0041\u0055\u0025\u0063\u004d\u004d\u0054\u006c\u0068\u0021\u0059\u005d\u0074\u0024\u0028\u007a\u0067\u006d\u007a\u0032\u0050\u006d\u0079\u0046\u0039\u0078\u007a\u0037\u0027\u0076\u002e\u0073\u0071\u004c\u0037\u0078\u0065\u0029\u0057\u003e\u0047\u0021\u0031\u003a\u003b\u003d\u0035\u005a\u0066\u003d\u007d\u0051\u0049\u004b\u0025\u0065\u0057\u0074\u0050\u006a\u0039\u007e\u0042\u003d\u003d\u0033\u005e\u0072\u0023\u0043\u007b\u0066\u0063\u0046\u0025\u005d\u0037\u003b\u0062\u004e\u0044\u0064\u0075\u007a\u007e\u0022\u0056\u0067\u0023\u006c\u0026\u0032\u0048\u0062\u0031\u0062\u0058\u007c\u0039\u0021\u0078\u0059\u0051\u0045\u002b\u0033\u0038\u003b\u0070\u006c\u0052\u0062\u0057\u003a\u006c\u006c\u004b\u0025\u0036\u003c\u0077\u005c\u0038\u0023\u002e\u0075\u003e\u0075\u004e\u0045\u0074\u0042\u007b\u004f\u0065\u0068\u0070\u002d\u007e\u004e\u002c\u007c\u0034\u0077\u0078\u0038\u0061\u0077\u0040\u004e\u0033\u0031\u0060\u0021\u0057\u003d\u0053\u0053\u003a\u0051\u0062\u0020\u0052\u007d\u005d\u0065\u0041\u0065\u0049\u0051\u005f\u0024\u0032\u0020\u0024\u0023\u0067\u002a\u006d\u007e\u002b\u006c\u0070\u0044\u003b\u0064\u003a\u0048\u007c\u002d\u0066\u004a\u0066\u005b\u004d\u0066\u0047\u007a\u0051\u0037\u0046\u0061\u005e\u0079\u007e\u003f\u003e\u0067\u0071\u004b\u0042\u0028\u0063\u0056\u0045\u0046\u007d\u002d\u0054\u0031\u003e\u0024\u006c\u0078\u0026\u0052\u003e\u002a\u0043\u0026\u007b\u002c\u0034\u0022\u0049\u0035\u0054\u0032\u0075\u0078\u0046\u0050\u007b\u002c\u0050\u0032\u0062\u003f\u0051\u0028\u0069\u007e\u0047\u0048\u0058\u0062\u002e\u007b\u003f\u007a\u003a\u0020\u0035\u0072\u004d\u0073\u0035\u003b\u0022\u007a\u0061\u006d\u003c\u0028\u0078\u005f\u005c\u006d\u0051\u0074\u0063\u002a\u004e\u004f\u004f\u0027\u0058\u0058\u003f\u0034\u0075\u0039\u006d\u0055\u0047\u003d\u0063\u0030\u0054\u0066\u006f\u0041\u0035\u007a\u0041\u0044\u003e\u0041\u004c\u005f\u0047\u002e\u0044\u005a\u0024\u0073\u0043\u0040\u007a\u0067\u0067\u0053\u006a\u005e\u0045\u0046\u0065\u0061\u006f\u002c\u002b\u003a\u006d\u005c\u0063\u004b\u002e\u0021\u005e\u002a\u0059\u0045\u0056\u0054\u002f\u0050\u0051\u004c\u007d\u004a\u0039\u0038\u0052\u007d\u006f\u0076\u0061\u0052\u0057\u002d\u007c\u004c\u0029\u0034\u0049\u0036\u002c\u004b\u004c\u0040\u0055\u0041\u0055\u0034\u0078\u004f\u0035\u0065\u0021\u0068\u0053\u0031\u0032\u0034\u0037\u0061\u0050\u0063\u005d\u007c\u004f\u006b\u0074\u0059\u0061\u006c\u0031\u0058\u0053\u0024\u0054\u002d\u0049\u0048\u0051\u0041\u007b\u0063\u0063\u006a\u005b\u007a\u006b\u002f\u0025\u0069\u0044\u0028\u004c\u0059\u006d\u0052\u0040\u002d\u0042\u006c\u0025\u0053\u0076\u003d\u0037\u0039\u004a\u005c\u0057\u002b\u0063\u003a\u006e\u0075\u0052\u0054\u0077\u0044\u004b\u0028\u003c\u0026\u005c\u0073\u0034\u0075\u0029\u005e\u003c\u0031\u004a\u0067\u004f\u007d\u002f\u006f\u0056\u0068\u003d\u0074\u0041\u007b\u0051\u003d\u0023\u0027\u0041\u0043\u007b\u0022\u006e\u007a\u004f\u002c\u0055\u0022\u002a\u0024\u0069\u0035\u0036\u0034\u006e\u0038\u0031\u0043\u007b\u0050\u0030\u0056\u0026\u0024\u002f\u0057\u0042\u0079\u007e\u0053\u0023\u0029\u006d\u0038\u0057\u004d\u0071\u0070\u0069\u007b\u005a\u0041\u007a\u007b\u0052\u0033\u0060\u0027\u0055\u0022\u0047\u004f\u003b\u007b\u007b\u0028\u0037\u0054\u0076\u0032\u006c\u006c\u0064\u0072\u006f\u0076\u0063\u0076\u0025\u0067\u0028\u005a\u007c\u0042\u0065\u002a\u005e\u002f\u0068\u0076\u0066\u002f\u0042\u005e\u0068\u006a\u0047\u005f\u0027\u005a\u006b\u0056\u0061\u0070\u006e\u0057\u002f\u0054\u0036\u004b\u006e\u0076\u005f\u005a\u0047\u0073\u002d\u0056\u0054\u0051\u007a\u003e\u005e\u0077\u006a\u0033\u006d\u0021\u0058\u0025\u0023\u0074\u004a\u0056\u0059\u003c\u0063\u003c\u002f\u0050\u0031\u0028\u004b\u0028\u0075\u0066\u0066\u0024\u006e\u0040\u004a\u005e\u006e\u003d\u0039\u0057\u0037\u002d\u007a\u006f\u0061\u004f\u006f\u003e\u005a\u0079\u0027\u006f\u0051\u0074\u0043\u0053\u005e\u005e\u006a\u0037\u005a\u005c\u0058\u006e\u0043\u0066\u0063\u0025\u0078\u0068\u0034\u0079\u002c\u003a\u0052\u0020\u0058\u005e\u004a\u005f\u005c\u0063\u003a\u0075\u0032\u0044\u0071\u006d\u0044\u005a\u0045\u0049\u006c\u006e\u004b\u003a\u0020\u002c\u0051\u0056\u0040\u0079\u003e\u0059\u007c\u0074\u0028\u006d\u0055\u0076\u0059\u0056\u002a\u005a\u0057\u0037\u0020\u0035\u0073\u0033\u0076\u0039\u004e\u006f\u0052\u003c\u0035\u006d\u006b\u0020\u0043\u0039\u0078\u003b\u0029\u005e\u0025\u0073\u0025\u0037\u005c\u003e\u004e\u0077\u0063\u004b\u002f\u0038\u0047\u0059\u004e\u0032\u0053\u0063\u0050\u0026\u0058\u0070\u0079\u007e\u0063\u0054\u007a\u0061\u0043\u003e\u0023\u007a\u0032\u0071\u0033\u0030\u003d\u0032\u0026\u006a\u006b\u0052\u007a\u004f\u0048\u0075\u0073\u003f\u0073\u006f\u0039\u006c\u0031\u0071\u0067\u0054\u007a\u0070\u002d\u0044\u002b\u0032\u007b\u0077\u002a\u0071\u0066\u0031\u003d\u006e\u0033\u002c\u0053\u0043\u0026\u0049\u0038\u0041\u0037\u0030\u003e\u0037\u006f\u006b\u003b\u005b\u0023\u007c\u0048\u004f\u007e\u0031\u005b\u002c\u002f\u0043\u0052\u0065\u0050\u0035\u003f\u0027\u002a\u005d\u0039\u0075\u0034\u0041\u0047\u0027\u002a\u0030\u0073\u0070\u0047\u003a\u003a\u006a\u005a\u0074\u0046\u0037\u0042\u0031\u0067\u003f\u004b\u0022\u007c\u0042\u0027\u0069\u0059\u0034\u002c\u0028\u0047\u003f\u003f\u0061\u0059\u003f\u0020\u005f\u0078\u0073\u005d\u0045\u005b\u0033\u002c\u0035\u007d\u0033\u004b\u006a\u003c\u0065\u0063\u0044\u0029\u0034\u003c\u0022\u0074\u002d\u006e\u006d\u0047\u002d\u0053\u0066\u0023\u004f\u0025\u0060\u002f\u0057\u007a\u002f\u005a\u0054\u0079\u0071\u0037\u0069\u0025\u0072\u0057\u0029\u0069\u0062\u0071\u0040\u0076\u0062\u004d\u005e\u0027\u0061\u0025\u0060\u0026\u0066\u002e\u0044\u0045\u003f\u006b\u0045\u0063\u0020\u002f\u0062\u0055\u0020\u0021\u003b\u0020\u003c\u005e\u0056\u0029\u0064\u0039\u003e\u0029\u0068\u0029\u006c\u0066\u0033\u0032\u0041\u007b\u006b\u0047\u005a\u0035\u0066\u002b\u003d\u0072\u002f\u007b\u0063\u0065\u006b\u002f\u003a\u004a\u0062\u0048\u004b\u0072\u0040\u0076\u0051\u0074\u0053\u0032\u0033\u0047\u0078\u0056\u002f\u0043\u002c\u0035\u0026\u0039\u0067\u0066\u007c\u0052\u0067\u005b\u005a\u0043\u0069\u0027\u0050\u0026\u0069\u006a\u003b\u007d\u003c\u0077\u002f\u007c\u0051\u0038\u002a\u0038\u0044\u007e\u002f\u0037\u0056\u005e\u007d\u004b\u003d\u005c\u0041\u0066\u003c\u0022\u0077\u002a\u002a\u0054\u0029\u007a\u004d\u0030\u0072\u0020\u0035\u0025\u007a\u0060\u005f\u0074\u007a\u0078\u0029\u0073\u0049\u004e\u0035\u002c\u0079\u0039\u0037\u0051\u0048\u0024\u002e\u0022\u0040\u004f\u005e\u006c\u0079\u0032\u005c\u0069\u0044\u0073\u0052\u0073\u004c\u0021\u0055\u0072\u0032\u0039\u0078\u0066\u005e\u003a\u0059\u0022\u0038\u003c\u0057\u0062\u006b\u0027\u0024\u006f\u004e\u0032\u004f\u002e\u0075\u002f\u0034\u003e\u0044\u0022\u0020\u0051\u0071\u002e\u0025\u002b\u0079\u003e\u0034\u005f\u0042\u0065\u0056\u0071\u0055\u0057\u002c\u0044\u0050\u005a\u0043\u0068\u003c\u0028\u0076\u007e\u0028\u0047\u0074\u0040\u004b\u0039\u002c\u0046\u005c\u003f\u0073\u0034\u0050\u002c\u007c\u0045\u0030\u0053\u004b\u0034\u0071\u0022\u002e\u006c\u0049\u004c\u0022\u0075\u0037\u0030\u005f\u0076\u0071\u007e\u003f\u003e\u0039\u0030\u0076\u003e\u003f\u004c\u0079\u0048\u004a\u006c\u0075\u007a\u004d\u0061\u007c\u004d\u0069\u0046\u004e\u0049\u005a\u0023\u003d\u0064\u0054\u0040\u0033\u0077\u0077\u0034\u005c\u004a\u0026\u0064\u006c\u004b\u003b\u005b\u0040\u0028\u0077\u004a\u0027\u0078\u0035\u0064\u004a\u003f\u0034\u0040\u0068\u0033\u0033\u003c\u0046\u0068\u006f\u0068\u002b\u0074\u0050\u0021\u006a\u005f\u006d\u0046\u0049\u0069\u0077\u0042\u0055\u0051\u002f\u0051\u007b\u007e\u0028\u0050\u0076\u0043\u0039\u0061\u0038\u0051\u004a\u003b\u0047\u0062\u0076\u0078\u0060\u0030\u0039\u0044\u0041\u0027\u007e\u005e\u0068\u0060\u006f\u0078\u0027\u0055\u0047\u0078\u007e\u006f\u0032\u002c\u0040\u0064\u0060\u007e\u0021\u002f\u003d\u0069\u0056\u002b\u006e\u003d\u0027\u005c\u007b\u0044\u0055\u0035\u0054\u006a\u0024\u0035\u0022\u0032\u0072\u0035\u0070\u0065\u0072\u0072\u007d\u0048\u004f\u0053\u002b\u0077\u007d\u003e\u007e\u0047\u002a\u0048\u0074\u0034\u0036\u006c\u0037\u003e\u0072\u0068\u0078\u0051\u0035\u0046\u0054\u005c\u004e\u002c\u0062\u0049\u0074\u0063\u0021\u0040\u004f\u0035\u0066\u0027\u0061\u0035\u005f\u0071\u0070\u0056\u0078\u0031\u0065\u0038\u0065\u004d\u0053\u0037\u003f\u007d\u006e\u0023\u0040\u0068\u0061\u004b\u0028\u0062\u007e\u002a\u0052\u0030\u0076\u0070\u004b\u002f\u0033\u004a\u0050\u0031\u005f\u003a\u002d\u0036\u003f\u0074\u003f\u0060\u0035\u002d\u0030\u007d\u005e\u006f\u0064\u006e\u004a\u005c\u005d\u0060\u0030\u007b\u0060\u0054\u006b\u002f\u002a\u003b\u0040\u0047\u0025\u006f\u0046\u006b\u0023\u0047\u0034\u006f\u0044\u002f\u0042\u0036\u005f\u0060\u0037\u004d\u0045\u0046\u007e\u005c\u007b\u005d\u002f\u0059\u002f\u0079\u0071\u0074\u0039\u005e\u0030\u0037\u006a\u003f\u0033\u004d\u006c\u006b\u0061\u0063\u0076\u002d\u004f\u0058\u0029\u005d\u0026\u0026\u0021\u0036\u005d\u0042\u002c\u006b\u0051\u0040\u0045\u0064\u0050\u007e\u0047\u0042\u0023\u005b\u002c\u0023\u0073\u0023\u0049\u002a\u0073\u004d\u0037\u0055\u0056\u0079\u0029\u0021\u0021\u003c\u0038\u002d\u007c\u0024\u0031\u0079\u0032\u0067\u0046\u0077\u0029\u0065\u0025\u002c\u002f\u005f\u0042\u005d\u007c\u0028\u002b\u004b\u0024\u0020\u0056\u0079\u007c\u0051\u0067\u0052\u005e\u0040\u0043\u004a\u0024\u0060\u0050\u0047\u004b\u0071\u002a\u006e\u007c\u007b\u0060\u002a\u0022\u004f\u0070\u0077\u005b\u0056\u0029\u0029\u0058\u006c\u0040\u003e\u004b\u005a\u003a\u0068\u0065\u0054\u006d\u0031\u002b\u005e\u002a\u0079\u0079\u005c\u0076\u006a\u0036\u0065\u003a\u0038\u007d\u0077\u005b\u0033\u0058\u0070\u007a\u0058\u002d\u005c\u0060\u006d\u007b\u0040\u0040\u005f\u0056\u0064\u0061\u0058\u004b\u002e\u006d\u0031\u0027\u0062\u004e\u0069\u002f\u0036\u0055\u0028\u003a\u0043\u0051\u0040\u0041\u0053\u0053\u0032\u0025\u0025\u0024\u0074\u0029\u0025\u0066\u0062\u003a\u0020\u0067\u002e\u0046\u004f\u0020\u0077\u0048\u0071\u0040\u003f\u0021\u0050\u0024\u003d\u0067\u0053\u007e\u0029\u006f\u0027\u0042\u002b\u0072\u0075\u0038\u005b\u005c\u0059\u0071\u0073\u0059\u0078\u004b\u0040\u0038\u0029\u0072\u0065\u0061\u005c\u005a\u006d\u0040\u005f\u004e\u0075\u006e\u0069\u0053\u0072\u0059\u0060\u005e\u005b\u0077\u0074\u0043\u0028\u0025\u0025\u0070\u0059\u0051\u007c\u006e\u0067\u0063\u002b\u0075\u0052\u002c\u0061\u006e\u0033\u0022\u005c\u003d\u005b\u004d\u0034\u0050\u0031\u0037\u004d\u0064\u0075\u0065\u0035\u0068\u006a\u0053\u0031\u0076\u0052\u0038\u0025\u005a\u006e\u004a\u0021\u0074\u0046\u004d\u006a\u0024\u002e\u0033\u0029\u0033\u002f\u004e\u0026\u0046\u0020\u007a\u003d\u007d\u007d\u006e\u0053\u0057\u003f\u0040\u007a\u007b\u0052\u004d\u004e\u0034\u007b\u0070\u0063\u005c\u003d\u0033\u0026\u0038\u005e\u004b\u0078\u003f\u0076\u0024\u0079\u0020\u007b\u005e\u0024\u0065\u0021\u0060\u0023\u002d\u0053\u0070\u0051\u0039\u005b\u0055\u0025\u0052\u005f\u004f\u007e\u0043\u004b\u0075\u0052\u0027\u0069\u006d\u005d\u0042\u003b\u0051\u0067\u004a\u0056\u003a\u0034\u0038\u007c\u0044\u002b\u007d\u0052\u0071\u0061\u0053\u0044\u006d\u005f\u0074\u0034\u0027\u007b\u0023\u0026\u0055\u003c\u0078\u0029\u0061\u0048\u0055\u0037\u005b\u002f\u002f\u0027\u002d\u004a\u0044\u0035\u005d\u006b\u002e\u003d\u004c\u003b\u0043\u0072\u0055\u0025\u004b\u0059\u0029\u004f\u0035\u0028\u0028\u0021\u004c\u0064\u0023\u0052\u0066\u007e\u0054\u0040\u0066\u0038\u003c\u0044\u0032\u004e\u002c\u0062\u005b\u0030\u003d\u006f\u0068\u0032\u0039\u002a\u0068\u002c\u0066\u0022\u0053\u0046\u0046\u002c\u0032\u0034\u0026\u0075\u0067\u0057\u0024\u007b\u0064\u005d\u005e\u0052\u0046\u007e\u0031\u003b\u003a\u0045\u0050\u0041\u005f\u0033\u003c\u003e\u0053\u004b\u0065\u0059\u004f\u0051\u0064\u003a\u0040\u0063\u0064\u0022\u0061\u0072\u003d\u0021\u0047\u0061\u004e\u004b\u0077\u005c\u006c\u004d\u002d\u003e\u0042\u0032\u0074\u0070\u0061\u002c\u0029\u0031\u006a\u0059\u004d\u0043\u0042\u006c\u0026\u0025\u0033\u005f\u0033\u0021\u0067\u003b\u0070\u0061\u0058\u0046\u005c\u004a\u0079\u0043\u0079\u0026\u0028\u0050\u0049\u0025\u0078\u002e\u007b\u003c\u0041\u0042\u0062\u0045\u0024\u0071\u0040\u0069\u005f\u0051\u003f\u0028\u002f\u0021\u0039\u007a\u0045\u0067\u004f\u007d\u005f\u0022\u0066\u002f\u002e\u0020\u0043\u0029\u005a\u006a\u0021\u0074\u004e\u003d\u0078\u0062\u007e\u0040\u0060\u0063\u0055\u0059\u0020\u002e\u0062\u0037\u0043\u002b\u0057\u007a\u0069\u004b\u0072\u002c\u0067\u005d\u0045\u003d\u0051\u002c\u004b\u004f\u0025\u005c\u0076\u0051\u005e\u0052\u0045\u007e\u0048\u0077\u0046\u0043\u0047\u0060\u007b\u003a\u006c\u0072\u0049\u0079\u006a\u003f\u0026\u0026\u0046\u0073\u006c\u007c\u0072\u002e\u006e\u006d\u002b\u003b\u002d\u0057\u0064\u0062\u006a\u0053\u0043\u0056\u0022\u004e\u0033\u0065\u003a\u0075\u0058\u0061\u0024\u0034\u0024\u0073\u0060\u0059\u002b\u0065\u0023\u0073\u0020\u0071\u002b\u007e\u0072\u005e\u0066\u0048\u006e\u0063\u0077\u0070\u0032\u003f\u0023\u0043\u0047\u0066\u003f\u0044\u0060\u007d\u005a\u005a\u0032\u0020\u0064\u0059\u0060\u0056\u0074\u0044\u0048\u0062\u0032\u0063\u0024\u0024\u0032\u0078\u006a\u0033\u005f\u005d\u0029\u004e\u0056\u004a\u0038\u004c\u0032\u0057\u0022\u0075\u0022\u0065\u003c\u0050\u003d\u005b\u002c\u0053\u003f\u006b\u0052\u0023\u0024\u0066\u005d\u005f\u007d\u0042\u003f\u0047\u0042\u0033\u0065\u0049\u0054\u0069\u0026\u004d\u006f\u0022\u0068\u007e\u0076\u0060\u0067\u005d\u007b\u0060\u007a\u007a\u002d\u0042\u004c\u0066\u005a\u006c\u0040\u0070\u0034\u006e\u0069\u0036\u006a\u0022\u0038\u0064\u0036\u0030\u004c\u0027\u0033\u002e\u0050\u006d\u0032\u0032\u0077\u007b\u006f\u0067\u0039\u0040\u004a\u0039\u002e\u0022\u002f\u0030\u002e\u003a\u003d\u005e\u002a\u006d\u0060\u007d\u007e\u0057\u0057\u0058\u0059\u0064\u0047\u002d\u0026\u002e\u0074\u0038\u0073\u0041\u0074\u005d\u0056\u005b\u005b\u003c\u0036\u003f\u0030\u0028\u0074\u006b\u004c\u0048\u007b\u0032\u0030\u003e\u0020\u0049\u005c\u003f\u002e\u004b\u0073\u0029\u004a\u007e\u0079\u004c\u0021\u0050\u003e\u0074\u004c\u005a\u006d\u003f\u0073\u0034\u002e\u0038\u003e\u006a\u0068\u0035\u0040\u006e\u004f\u0065\u003c\u0023\u002f\u0041\u0025\u006c\u0061\u0023\u005f\u004c\u003e\u0039\u0034\u0060\u0051\u0070\u0039\u0044\u005f\u0064\u0073\u0067\u0031\u0055\u0068\u0051\u002e\u006c\u0079\u004a\u0070\u0062\u0063\u005c\u0068\u0062\u0077\u0025\u0021\u0028\u0033\u0049\u005e\u0028\u002c\u0053\u006d\u0033\u0022\u006e\u0056\u0074\u0036\u002b\u006a\u0074\u0043\u005a\u0030\u0064\u0047\u003d\u005b\u004b\u0074\u0068\u006f\u007c\u0053\u005c\u0068\u004d\u007e\u003d\u0046\u006b\u007d\u006b\u0026\u0072\u0066\u0038\u0061\u006b\u0043\u0077\u003a\u006c\u0055\u0020\u0035\u0071\u0042\u0062\u0074\u0032\u005a\u004a\u0031\u004a\u0020\u0026\u0021\u0042\u0070\u003b\u004c\u004d\u0040\u0070\u0048\u0061\u0035\u0077\u0063\u0039\u0059\u002d\u002b\u0060\u006a\u0063\u005d\u003f\u0039\u0056\u0049\u006c\u005d\u007d\u0036\u0079\u0061\u003b\u0071\u007c\u0052\u002e\u004f\u0034\u0074\u004b\u002e\u006f\u0064\u006b\u002f\u006d\u002a\u0047\u006b\u002d\u005d\u0068\u0041\u006f\u004a\u0076\u0031\u0028\u006b\u0061\u006b\u003f\u003a\u0067\u0070\u002b\u0055\u0034\u007c\u0038\u0028\u006f\u0039\u0049\u0043\u0067\u0048\u0051\u0032\u007e\u0070\u0024\u005e\u0062\u0072\u007d\u0070\u0034\u0028\u0075\u0049\u004f\u0052\u005d\u0045\u007a\u0079\u005f\u006a\u002a\u0055\u007c\u007d\u0059\u0024\u0077\u0070\u0067\u004c\u006b\u0047\u004f\u0063\u005d\u002f\u006f\u0058\u0062\u007a\u0044\u007b\u0066\u0067\u0065\u003d\u002c\u004e\u0043\u0078\u0025\u0054\u0042\u0073\u0050\u0047\u0056\u0055\u007b\u0061\u0049\u0060\u0055\u0038\u0040\u0057\u0074\u0077\u0020\u003f\u004d\u007c\u002f\u0026\u0021\u002a\u0060\u003b\u002f\u003c\u0048\u0059\u005f\u006f\u0035\u0050\u004a\u0023\u0044\u0035\u007e\u006e\u003c\u0074\u007e\u006f\u0077\u0023\u006b\u0046\u006e\u0031\u006f\u0055\u0033\u004b\u0033\u0028\u0078\u005c\u0072\u0067\u0074\u0030\u006a\u006b\u005d\u0079\u007e\u0065\u006d\u003e\u006c\u0058\u006b\u0021\u0063\u0064\u0049\u002a\u0022\u0049\u004d\u004a\u004d\u0022\u0033\u0032\u002f\u007c\u0043\u006f\u0044\u0028\u0048\u0055\u0065\u0061\u0062\u0056\u002a\u0027\u006e\u004b\u0060\u0048\u0070\u003d\u007d\u0037\u0023\u0069\u0047\u0028\u0036\u0069\u0029\u003c\u0037\u0043\u0055\u0043\u0071\u0067\u0028\u0064\u0034\u0069\u0021\u0061\u0064\u0076\u0025\u0029\u0063\u0074\u006b\u003a\u0037\u005d\u007b\u007b\u002c\u0077\u0060\u0057\u0078\u0063\u0044\u0066\u005a\u0055\u003c\u0042\u004a\u005f\u005f\u0021\u0035\u0054\u0057\u004c\u0023\u0021\u0059\u0073\u0023\u003b\u0053\u002a\u0049\u003b\u0039\u0020\u0074\u005d\u0046\u0051\u005c\u004e\u006a\u0037\u0058\u0051\u006b\u0059\u0032\u0069\u0045\u007b\u004a\u0036\u0035\u0076\u0051\u003e\u0049\u0055\u005b\u005e\u0027\u003a\u006f\u0032\u004a\u0034\u0070\u003a\u0066\u002b\u0059\u0032\u0047\u005e\u0022\u0027\u003b\u007d\u0058\u0033\u0049\u0060\u004f\u0044\u007c\u0037\u0033\u0072\u0032\u005f\u0052\u007e\u0035\u003f\u0021\u002a\u0035\u0027\u0064\u0063\u0066\u003d\u0058\u007a\u002e\u0076\u005d\u0040\u0074\u006c\u004e\u0074\u006c\u0041\u0050\u007d\u0079\u007a\u0070\u0079\u006c\u003a\u002d\u0035\u003f\u0049\u004b\u0022\u0038\u0061\u0071\u0079\u0065\u007b\u0048\u0032\u0056\u0064\u005a\u0029\u0035\u007a\u0047\u0034\u005a\u0078\u0067\u0040\u0022\u0049\u0048\u0056\u0054\u003a\u0052\u0023\u0020\u0037\u0047\u0073\u006b\u0038\u0023\u0048\u0074\u0051\u0065\u0069\u0053\u0036\u006f\u004d\u0067\u0064\u002d\u006d\u0030\u007a\u0051\u0055\u002f\u0022\u0048\u0040\u004a\u0066\u006e\u002f\u0066\u0054\u0020\u005d\u0059\u0054\u0045\u0055\u0074\u0045\u0054\u0021\u0060\u0067\u0074\u0068\u0073\u0060\u007c\u0039\u0028\u0029\u004a\u0026\u002f\u0043\u0053\u0039\u006f\u0048\u0057\u003f\u0029\u0029\u0048\u0075\u003a\u0078\u0048\u002f\u0032\u005f\u0041\u006e\u0054\u0024\u0046\u004c\u007e\u0062\u0031\u004e\u006f\u0062\u005e\u0044\u0077\u0055\u006a\u0047\u002c\u0063\u004f\u0021\u003f\u005f\u002e\u0055\u0025\u003a\u005b\u0078\u0020\u0077\u0057\u005b\u0022\u0055\u0032\u0058\u0031\u004b\u0054\u002e\u006c\u003e\u005a\u004d\u0051\u0040\u0034\u002a\u0055\u0031\u004b\u0021\u0042\u0035\u005e\u0042\u0052\u0061\u0031\u005f\u0061\u0077\u0078\u0056\u004e\u0024\u0059\u0058\u006f\u005d\u0024\u002a\u002b\u0049\u0044\u0046\u0044\u0051\u0079\u0032\u0038\u0047\u0027\u002e\u0042\u0068\u0022\u002f\u002e\u0051\u0022\u0033\u0039\u004e\u006d\u0053\u0052\u0037\u0030\u002e\u0051\u004b\u0039\u003b\u0035\u003b\u007c\u007a\u0049\u0065\u0078\u004c\u0025\u0027\u005b\u0029\u003c\u006f\u0038\u0063\u004e\u003a\u0028\u0076\u0058\u0042\u0072\u003a\u007a\u0054\u0023\u0030\u0021\u005f\u0050\u0041\u007c\u0076\u0067\u0062\u0032\u0038\u007b\u006b\u006b\u0025\u0046\u006e\u0048\u005f\u0045\u0072\u0023\u005a\u0045\u005a\u0075\u005a\u0047\u006e\u004b\u004f\u0026\u0033\u004f\u0075\u0079\u0066\u0026\u0043\u0030\u0029\u002d\u0034\u003b\u0027\u002a\u0073\u0025\u0054\u004a\u0068\u0078\u0031\u0052\u0064\u0058\u0050\u0066\u0050\u0045\u0074\u0026\u0028\u0047\u0051\u0063\u0046\u003f\u0029\u0029\u005c\u0059\u0043\u005d\u0030\u006e\u0039\u0037\u006a\u0061\u005d\u0051\u005e\u0070\u0035\u002d\u0028\u0077\u0020\u0076\u0074\u007c\u0023\u0020\u0051\u0066\u002c\u002a\u0062\u007c\u003b\u0035\u005c\u0069\u004b\u002a\u0042\u003f\u0033\u0026\u0029\u0069\u0024\u0072\u003c\u0034\u0040\u0022\u0067\u0070\u0020\u0071\u0032\u007d\u0030\u003d\u0029\u0049\u003a\u0027\u0042\u0073\u0028\u0070\u006b\u0076\u0073\u0076\u0077\u0033\u006c\u002f\u0035\u0055\u0031\u0033\u0046\u0043\u007a\u0073\u0067\u0034\u0046\u004f\u002b\u006b\u0040\u0043\u0055\u0039\u003e\u004d\u0044\u0023\u005c\u0077\u0041\u006e\u0061\u006f\u004f\u0055\u006c\u005a\u004c\u005c\u0058\u0029\u0024\u004d\u0034\u0033\u0031\u0036\u0031\u0050\u0032\u0075\u007c\u007a\u0041\u0027\u003d\u0069\u0079\u0026\u0039\u006d\u007c\u003c\u0024\u007d\u003a\u0036\u0034\u0069\u0043\u003f\u0064\u007c\u002d\u0026\u003e\u0036\u0065\u0058\u0022\u002c\u0079\u0068\u0055\u004f\u005e\u004c\u006d\u002e\u0039\u004b\u0074\u003c\u003f\u002c\u0031\u005d\u0028\u0072\u003f\u0037\u0065\u0048\u0024\u0063\u0048\u0048\u0039\u002a\u0039\u002d\u006d\u0077\u002c\u006b\u0023\u007c\u002f\u002a\u005b\u003b\u0047\u0065\u002e\u0054\u0069\u005b\u0024\u002a\u005d\u0038\u0036\u004c\u0031\u004b\u0034\u0045\u003e\u0059\u007d\u002c\u005f\u0027\u004a\u0077\u003e\u0076\u0030\u0055\u0020\u002e\u005c\u007d\u007b\u0029\u005c\u0059\u0046\u0063\u0053\u0058\u004a\u0020\u0068\u006d\u005c\u004c\u004f\u0054\u003f\u0041\u0032\u004b\u0077\u0026\u002f\u0033\u0040\u0054\u007e\u003c\u005d\u0051\u004b\u0032\u0034\u0021\u006e\u0042\u0053\u002b\u005e\u0053\u005c\u0047\u0054\u004b\u005b\u0058\u007d\u0021\u004a\u0060\u0045\u0035\u0054\u0045\u002b\u0033\u0041\u002d\u0056\u0055\u0031\u0044\u0043\u007e\u0065\u005f\u007b\u007e\u0053\u0020\u0054\u0020\u0024\u006d\u0078\u0065\u005a\u0053\u0026\u0069\u0031\u005a\u0055\u003b\u006c\u0030\u0026\u0044\u0026\u002c\u0058\u0044\u0042\u006a\u005e\u0077\u002f\u0022\u0056\u005c\u0034\u003e\u004a\u0034\u005e\u0054\u0021\u0022\u0046\u0045\u003f\u004d\u004e\u006e\u0040\u007b\u0040\u0026\u0067\u0078\u007c\u004a\u003d\u0036\u002c\u0068\u003d\u007a\u0076\u002f\u0026\u003a\u003c\u0042\u0033\u005d\u0053\u005f\u0073\u0056\u0077\u007d\u006a\u005c\u0042\u006d\u0051\u006c\u0057\u0077\u006e\u0057\u0036\u0062\u002b\u0064\u002d\u0053\u003e\u003e\u0060\u005f\u004a\u0052\u0021\u002e\u004f\u005b\u0068\u005a\u0021\u0074\u004c\u0052\u003a\u0034\u006b\u002e\u0054\u0048\u0070\u004f\u0039\u005b\u0078\u006c\u002b\u002a\u0028\u005c\u0053\u006b\u0030\u004a\u0021\u006f\u0047\u0074\u002e\u007c\u0039\u0061\u004b\u0062\u004d\u0074\u0034\u003d\u0038\u0025\u0060\u003b\u002f\u0055\u0042\u0041\u0046\u0030\u0032\u0024\u0034\u0067\u0056\u0075\u003f\u006c\u0023\u0040\u0024\u0072\u0040\u004b\u0073\u0061\u003f\u003d\u0055\u0034\u0027\u003b\u007c\u005e\u0075\u0074\u0059\u0056\u003f\u0072\u006c\u0039\u0079\u0062\u0072\u0075\u0052\u0043\u0068\u005f\u003a\u0059\u0066\u0074\u0050\u0077\u0075\u0038\u0069\u007d\u0064\u002b\u0078\u006c\u0049\u0022\u0069\u0055\u006a\u005c\u006e\u0024\u0055\u0041\u0044\u0075\u002d\u0035\u0023\u0057\u0062\u003b\u0063\u007b\u0073\u004c\u003f\u004d\u002e\u0075\u005a\u005f\u002a\u003c\u0047\u0052\u003e\u007b\u0023\u0072\u0050\u006e\u0063\u007b\u002c\u0076\u0046\u003d\u0050\u0063\u005b\u0060\u0028\u006d\u0032\u005d\u0058\u0038\u0058\u0031\u0073\u002a\u0047\u006d\u0061\u006d\u005e\u005c\u0043\u0066\u0066\u0023\u0057\u005b\u0036\u0058\u007d\u006b\u0024\u0054\u0060\u0057\u0054\u0033\u0043\u0075\u002f\u0020\u0030\u0079\u0042\u003c\u0065\u0052\u002f\u0078\u006d\u0038\u002b\u006f\u0030\u0040\u0074\u003b\u007b\u002c\u006d\u004a\u0058\u006b\u0037\u0028\u0049\u0055\u006a\u0074\u004c\u003f\u0050\u0037\u0055\u0074\u0077\u0061\u0036\u0070\u0059\u007d\u0059\u0034\u0055\u002e\u0054\u0066\u0053\u003c\u0030\u004d\u004a\u0062\u0041\u0067\u0027\u0029\u0041\u0071\u0079\u0068\u0078\u0026\u0072\u0073\u0035\u005e\u0062\u005b\u003e\u0022\u006c\u003b\u0055\u0028\u003b\u003a\u0078\u006d\u006e\u0020\u0071\u0071\u005f\u0065\u0058\u0056\u0077\u0038\u007c\u0034\u0067\u0062\u0045\u0025\u002c\u0066\u0068\u0023\u004f\u006f\u0024\u006d\u003b\u0075\u0051\u0058\u005d\u006a\u003b\u005f\u005b\u0067\u0043\u0035\u004a\u0034\u005e\u003b\u005a\u0066\u004c\u0025\u006a\u0059\u007a\u0046\u0057\u003e\u006e\u0056\u002a\u0075\u0023\u0033\u0037\u0049\u005b\u0064\u0054\u0039\u0043\u0077\u0069\u0062\u0069\u0021\u0020\u006b\u0045\u0067\u0037\u0039\u004d\u0051\u006d\u0078\u0078\u004e\u0020\u003f\u0073\u007e\u003e\u0062\u002a\u0035\u003f\u002a\u002f\u006f\u0027\u0078\u0066\u002e\u0067\u0059\u0067\u0033\u0046\u003c\u0039\u0021\u0030\u0034\u006d\u0077\u0075\u0034\u0029\u0077\u006d\u0043\u005a\u0040\u0060\u0030\u006f\u006e\u007e\u0040\u0030\u0028\u006e\u0045\u0034\u0021\u0040\u0040\u007a\u0071\u004f\u0037\u0078\u0036\u0068\u0024\u0057\u006e\u0068\u0022\u0020\u0064\u0046\u005b\u004b\u0058\u0061\u007c\u003b\u006f\u0023\u0038\u0064\u003f\u0056\u0043\u006c\u0077\u0078\u0047\u006b\u0075\u007a\u0069\u005c\u007a\u0035\u0041\u0076\u0023\u0037\u007e\u007c\u0054\u0071\u006f\u0070\u002b\u0020\u004b\u004a\u006c\u0029\u003b\u0077\u0021\u0031\u0078\u002e\u0057\u0021\u0046\u005f\u0079\u006f\u0077\u0040\u0034\u0067\u005d\u0045\u0037\u0040\u006f\u0064\u006d\u004d\u0065\u006a\u0032\u007b\u0060\u0027\u0030\u0078\u0053\u005b\u002a\u0042\u006e\u0025\u0025\u0058\u0030\u002b\u0028\u005b\u003d\u0042\u0053\u004e\u0048\u0072\u0036\u0031\u0052\u0040\u006f\u0073\u0066\u0035\u0029\u004b\u0070\u005c\u004e\u002f\u005d\u002c\u0049\u0033\u006d\u0020\u0072\u002d\u0057\u0020\u0062\u003c\u0045\u006c\u0056\u003e\u0074\u007a\u0078\u0078\u002b\u005e\u005f\u0052\u003e\u0041\u0052\u0022\u003d\u006e\u006d\u006f\u004d\u004d\u0021\u0051\u005f\u0022\u004b\u002c\u0077\u005e\u002d\u0071\u0022\u003d\u0023\u0069\u0076\u007b\u0075\u0066\u003c\u0066\u0061\u0069\u003f\u0034\u0027\u003e\u0061\u003d\u0053\u0072\u0022\u006d\u0040\u004c\u0049\u0027\u003f\u0055\u0044\u002a\u0041\u0072\u002f\u002e\u0026\u0077\u004f\u005f\u0037\u0031\u0051\u0063\u004a\u0077\u0060\u0062\u005b\u005d\u0069\u0030\u006a\u0078\u004e\u0056\u0042\u0020\u0057\u003c\u0060\u003c\u0050\u0031\u0059\u0034\u005e\u0062\u0078\u0020\u002d\u0070\u004b\u0079\u0069\u007b\u005e\u0062\u0068\u0057\u0024\u006b\u004d\u0057\u0021\u0064\u002d\u007b\u0040\u005c\u0044\u0061\u0073\u0030\u0057\u0073\u007d\u007c\u0030\u005e\u0028\u005a\u0045\u002e\u004e\u0045\u0056\u0074\u0022\u0058\u0028\u0026\u0056\u0032\u0063\u0068\u0046\u0060\u0031\u0072\u0046\u0020\u0032\u007b\u006a\u002a\u0063\u0041\u002f\u0055\u0051\u005f\u007c\u007e\u003a\u0063\u0063\u0027\u0027\u0057\u0041\u005a\u007d\u002a\u0025\u0052\u005b\u006f\u0068\u0020\u0037\u0042\u0036\u003f\u0041\u006e\u0021\u0067\u0071\u0034\u0060\u0069\u0049\u0041\u004c\u004c\u0058\u0047\u005e\u002c\u0077\u0028\u005a\u006d\u0070\u0074\u0029\u0030\u0034\u003f\u0054\u0038\u006d\u004b\u0022\u0053\u003b\u0044\u0045\u003e\u003b\u005d\u0068\u0020\u0041\u006e\u004b\u007a\u0076\u0070\u0068\u005e\u004b\u004e\u0043\u0057\u003e\u0052\u0026\u0046\u004e\u007b\u0028\u0043\u006c\u005f\u004a\u003c\u0070\u002b\u004a\u0037\u0052\u0068\u007a\u005e\u007b\u0028\u0021\u004d\u0038\u003f\u004d\u0029\u0047\u0078\u0038\u0050\u006b\u0022\u006e\u0037\u002d\u0028\u005b\u0063\u004d\u0027\u0021\u0064\u0035\u0073\u004f\u0045\u005f\u0021\u0034\u0041\u005d\u0037\u0031\u004d\u0052\u0034\u005d\u0056\u003e\u006a\u0030\u0049\u0062\u002e\u0071\u003e\u0021\u0025\u0031\u0070\u007b\u0032\u0039\u0079\u003a\u0020\u0052\u0020\u006a\u0057\u0031\u0055\u0021\u006b\u0067\u0039\u002d\u0074\u0023\u005f\u0020\u0062\u006d\u007c\u004c\u0028\u002c\u0029\u0058\u006c\u0074\u003e\u004a\u0071\u007e\u003a\u007a\u007d\u0069\u0078\u0041\u0041\u0044\u006a\u007a\u0061\u0046\u0079\u004b\u0060\u005a\u0052\u0054\u0063\u005a\u006a\u0042\u0079\u0024\u004a\u002b\u003b\u0023\u0036\u0035\u0021\u0046\u004e\u0051\u0063\u004c\u006c\u006d\u002f\u0058\u0051\u0069\u005d\u003e\u004a\u0050\u0057\u0028\u0044\u0049\u002b\u0063\u0042\u0063\u0075\u0045\u0052\u003a\u005d\u0047\u004d\u0033\u0052\u0043\u007d\u0046\u0045\u0066\u0069\u0036\u0064\u0061\u0060\u006b\u0045\u0025\u0045\u004c\u002b\u005d\u0067\u004d\u007c\u002c\u0030\u0056\u0020\u0052\u0031\u0025\u007e\u0070\u004f\u0059\u0077\u0022\u0039\u004f\u0066\u003c\u0023\u002f\u0079\u0069\u0030\u0072\u003f\u0054\u0059\u0036\u0054\u007a\u0059\u006c\u0051\u0053\u003a\u006a\u003b\u0066\u0057\u0059\u0075\u003b\u002d\u0031\u0040\u007e\u0050\u0043\u005c\u0038\u003a\u007e\u004f\u004f\u002a\u004a\u0042\u0075\u0073\u0060\u003e\u0052\u0075\u0021\u0048\u0024\u003b\u007e\u0036\u0045\u004e\u0038\u0075\u006b\u0071\u0034\u005c\u002c\u0079\u004e\u0050\u0072\u006d\u0043\u006a\u005c\u006c\u0072\u0053\u0063\u005e\u0050\u0027\u0022\u0042\u007e\u0051\u006c\u0040\u0047\u003e\u0070\u002b\u0070\u0043\u0060\u003b\u0033\u006e\u007c\u007b\u0039\u007c\u0061\u0059\u0078\u0027\u0064\u0045\u0042\u0059\u007d\u0059\u004f\u0050\u0032\u003d\u0021\u002a\u0054\u007d\u005a\u007d\u0060\u0079\u004f\u0038\u0060\u005b\u0054\u0056\u0069\u007b\u002a\u0062\u0027\u0023\u0067\u007a\u0059\u007e\u0037\u0064\u0071\u007e\u0049\u0039\u0032\u0054\u0071\u0056\u0072\u0068\u0045\u0054\u0053\u005a\u006b\u0063\u0028\u006b\u0067\u0033\u002e\u0079\u002f\u0076\u0028\u0057\u0021\u0061\u0032\u002e\u0072\u0021\u005a\u0053\u007a\u0042\u003c\u004b\u0057\u0078\u0044\u0060\u003a\u0054\u002f\u002b\u0021\u0071\u0073\u0024\u0024\u0035\u006d\u0046\u0059\u0072\u0070\u002a\u0043\u003b\u0022\u0030\u0034\u0024\u0023\u005c\u0040\u005a\u006c\u0070\u006f\u0024\u006d\u004f\u0057\u003f\u0039\u006e\u0043\u007a\u0059\u0078\u0028\u0030\u0037\u0051\u0057\u0065\u0040\u0044\u007d\u0057\u003f\u003b\u0076\u0035\u006a\u0046\u006f\u0044\u002f\u0056\u0072\u006e\u002c\u0023\u0074\u0033\u002d\u0066\u0043\u0030\u007e\u002f\u0058\u0060\u0046\u003c\u0042\u0028\u006e\u002b\u0077\u0047\u006d\u004d\u006b\u0067\u002d\u0061\u005f\u0043\u0033\u004f\u004c\u0057\u0054\u002a\u003e\u006f\u005e\u0033\u0041\u0051\u0067\u007e\u007a\u0072\u004a\u007a\u0045\u0048\u0044\u006f\u0036\u0052\u003f\u007a\u0053\u0041\u0044\u0034\u007c\u0046\u003f\u006a\u003c\u0037\u0031\u0047\u003c\u0021\u0061\u0024\u0056\u0043\u0064\u0063\u002a\u0024\u0038\u005d\u004f\u0034\u0042\u005d\u0038\u0043\u0033\u0079\u0034\u005a\u007c\u0048\u0064\u006d\u0037\u0057\u0049\u0051\u0068\u002c\u003c\u0058\u0062\u0028\u0022\u0021\u0053\u007d\u0075\u0055\u0047\u0064\u0032\u0067\u004b\u004a\u0079\u0061\u0069\u0051\u006d\u0065\u0041\u0028\u0024\u004a\u0069\u0023\u0027\u0064\u007c\u005d\u002c\u0034\u004c\u0056\u006b\u0026\u003a\u0075\u0066\u0041\u0070\u0043\u002d\u007c\u0063\u002d\u007c\u005d\u0039\u0063\u0047\u003c\u0033\u0030\u0023\u002a\u0065\u0070\u003c\u0065\u005a\u007d\u0052\u003c\u0051\u0074\u0021\u0077\u0037\u006f\u0075\u0044\u0022\u006e\u0040\u0042\u0032\u0051\u0031\u0034\u0052\u004f\u0024\u0057\u007a\u0059\u0058\u0035\u007e\u0062\u0074\u0041\u003a\u0050\u005d\u0025\u005f\u003d\u0021\u002a\u003d\u0069\u0038\u0053\u007b\u0025\u0031\u0062\u003b\u0051\u006e\u0048\u005b\u003c\u0047\u0079\u005e\u0032\u0035\u0056\u005b\u0055\u0073\u0029\u0036\u0020\u0059\u0073\u006b\u0031\u002e\u005f\u0064\u005d\u0044\u007e\u0047\u0070\u0045\u0041\u0053\u0058\u0034\u006f\u0041\u002e\u0056\u0059\u003d\u0067\u0064\u005a\u0021\u0061\u0057\u0068\u0036\u0024\u0026\u0038\u0050\u0020\u0056\u0046\u006f\u0043\u0072\u0073\u002e\u0073\u005f\u007d\u0063\u004d\u007a\u0068\u0032\u003e\u0038\u0061\u0035\u0048\u0020\u0052\u0071\u0033\u0023\u0035\u0031\u0040\u003a\u0070\u0061\u0034\u0054\u0024\u0020\u0029\u0078\u005f\u0061\u0025\u0075\u003c\u0055\u005c\u0023\u003f\u0027\u007d\u0071\u004f\u003c\u0076\u0049\u004f\u0020\u0047\u0047\u004b\u0031\u004d\u002b\u0064\u006a\u007b\u0049\u0030\u003d\u0049\u0078\u0045\u002b\u0040\u0061\u003d\u0060\u004a\u0033\u0065\u004f\u0021\u004e\u0031\u005d\u0079\u006b\u0043\u005b\u002b\u002a\u0072\u002e\u002d\u0077\u0065\u0059\u0057\u0020\u0072\u0061\u0069\u007a\u0045\u0042\u0062\u0073\u003a\u0032\u0044\u0053\u006e\u002f\u0057\u007b\u007c\u0043\u0061\u007d\u0052\u0075\u003b\u0071\u0044\u0033\u0079\u002b\u0021\u003a\u0030\u0058\u0067\u0056\u0061\u0071\u0035\u0045\u0069\u006e\u0067\u005a\u003a\u0049\u0055\u005f\u004f\u0061\u005d\u0031\u0032\u0046\u0079\u003f\u0027\u0056\u0042\u0055\u0037\u0041\u004e\u0022\u0024\u0052\u002d\u0023\u0056\u006e\u005a\u0057\u006f\u0028\u0028\u0020\u002b\u004a\u0034\u005b\u0022\u002d\u0067\u0072\u0075\u0052\u0020\u003a\u005e\u006e\u0024\u007b\u0030\u0030\u003f\u005f\u0053\u0043\u0035\u0028\u0069\u007a\u004f\u005c\u0078\u0059\u0033\u0069\u003e\u0067\u003f\u006f\u003a\u002f\u0049\u0061\u003b\u0045\u0025\u007e\u0036\u002a\u0079\u0029\u0074\u0064\u007e\u0036\u0053\u0065\u0062\u0021\u002b\u0058\u006c\u0031\u0040\u004f\u0059\u0030\u0045\u0078\u002e\u0043\u0049\u0035\u002f\u007d\u0031\u0066\u006a\u006d\u004a\u0038\u0038\u0067\u0032\u0023\u0024\u0076\u006a\u004b\u0043\u006c\u0020\u0069\u004d\u007e\u0048\u0063\u0056\u007a\u0077\u0059\u0051\u007c\u0070\u0065\u0031\u0026\u0028\u0078\u0038\u0075\u0034\u005e\u0039\u002e\u004a\u0075\u0071\u0029\u0026\u004d\u0045\u0043\u004f\u0043\u0064\u0049\u0041\u0074\u004c\u0071\u0020\u003d\u0028\u0062\u0075\u0070\u0077\u0051\u0077\u0050\u0031\u0026\u0032\u0037\u0033\u0074\u0056\u0077\u0057\u004c\u005e\u0050\u005a\u0063\u0034\u0053\u0074\u004d\u0040\u0026\u0028\u0079\u003b\u007e\u003f\u005e\u005e\u0079\u005b\u0071\u0056\u0053\u0049\u005f\u0062\u0063\u002b\u0068\u0068\u0031\u0061\u0026\u0032\u006e\u0033\u0053\u0068\u0069\u0049\u0036\u005d\u006e\u0066\u007a\u0063\u006b\u006c\u0024\u005a\u002d\u007d\u005e\u003f\u0077\u0079\u0077\u0070\u0045\u0079\u006c\u0039\u0053\u0070\u003b\u0048\u0071\u003a\u0041\u006c\u003b\u005e\u0040\u0041\u0041\u0054\u004b\u007c\u006b\u0076\u0059\u004b\u0044\u0023\u007d\u0061\u0044\u007b\u003c\u0024\u006b\u0054\u0076\u0057\u004e\u0052\u006d\u0079\u0056\u0075\u0025\u0028\u0031\u0045\u0051\u003c\u003f\u0043\u0066\u004b\u0047\u0041\u0073\u0027\u0029\u0057\u004f\u0071\u0035\u0062\u0076\u0040\u0069\u0066\u0047\u0066\u0067\u0066\u002c\u0066\u0073\u0043\u0035\u0033\u004b\u0058\u0032\u003c\u0078\u0053\u006d\u005c\u0045\u0073\u0035\u005d\u0022\u003e\u0025\u004d\u002a\u0078\u0028\u0066\u002f\u0048\u003d\u0072\u006f\u0026\u0025\u0038\u003b\u002e\u0052\u002b\u007b\u004b\u006f\u0065\u0049\u0063\u004a\u0037\u0041\u0020\u004d\u0068\u002e\u0065\u0034\u0029\u0039\u0026\u006f\u0056\u007b\u0067\u0039\u0025\u0021\u003b\u0058\u0042\u0020\u0064\u006c\u0059\u0054\u0040\u007b\u0056\u0026\u0070\u0070\u005e\u0067\u002d\u0039\u0040\u006c\u0041\u0040\u002c\u0040\u002c\u0045\u005f\u0039\u006b\u006f\u007b\u007a\u004d\u004e\u0036\u0049\u0076\u0049\u0028\u0039\u004d\u0079\u0061\u0074\u004a\u0067\u0022\u005b\u0051\u0076\u0074\u0075\u0071\u005e\u0055\u003b\u0061\u0041\u005d\u0076\u0037\u002b\u0043\u005a\u0031\u0052\u0042\u0065\u0076\u006e\u0040\u0028\u0072\u0039\u0052\u006f\u007e\u007a\u002a\u0045\u003b\u0029\u002f\u0057\u0032\u005b\u006c\u0039\u0045\u002a\u004a\u0060\u0022\u007b\u0063\u0057\u003f\u006d\u005c\u0072\u0075\u0033\u0024\u0033\u005f\u0060\u0035\u005d\u0049\u0040\u0078\u0026\u002a\u0038\u0031\u007c\u006f\u0076\u0063\u003e\u0075\u006f\u0069\u0043\u0071\u0064\u0068\u0038\u0035\u007e\u0021\u0030\u002f\u0025\u0060\u004f\u002f\u0061\u0030\u005d\u0030\u005f\u0058\u0027\u0069\u0060\u0032\u0064\u0058\u007c\u007a\u005a\u0026\u002e\u005e\u007d\u0027\u0079\u006f\u007b\u004a\u006e\u0062\u0032\u004b\u002f\u0044\u005a\u006e\u0045\u0038\u006b\u003b\u0046\u0049\u005c\u0061\u0071\u002f\u0040\u0058\u0024\u0038\u0067\u002a\u0077\u0035\u0061\u0064\u002e\u004e\u0075\u0039\u0055\u004e\u0047\u002f\u0032\u007b\u003b\u007d\u003b\u0062\u005c\u005f\u002e\u0039\u0059\u005c\u0028\u0046\u0021\u003c\u002c\u0079\u0055\u0046\u005f\u0055\u0043\u0064\u004d\u0031\u003b\u003c\u0075\u005f\u0072\u0056\u0045\u0065\u003c\u005c\u005f\u004b\u007e\u0078\u0053\u002c\u0052\u0067\u0056\u004c\u003b\u0022\u0032\u0047\u0071\u0059\u0038\u0051\u0074\u0022\u0065\u005d\u0061\u002e\u002c\u0047\u0074\u007a\u0072\u0026\u0024\u003a\u0079\u007c\u0073\u0047\u003b\u005a\u005d\u0069\u002c\u0063\u0041\u0037\u004f\u0033\u0043\u0070\u0042\u0063\u0079\u007c\u0079\u0048\u004b\u0069\u0028\u0064\u0070\u0025\u0051\u0048\u0065\u0069\u0042\u0077\u0056\u0066\u0055\u0029\u003b\u0040\u0035\u0034\u0049\u0068\u0035\u0070\u0059\u007c\u003d\u0074\u005b\u0034\u005e\u0063\u0061\u0043\u006c\u0078\u0079\u0060\u0022\u003f\u004e\u005e\u006a\u002e\u003d\u0060\u0055\u005a\u0075\u0052\u0065\u0029\u004e\u006c\u0079\u006f\u002e\u0070\u0055\u003d\u0053\u005d\u006f\u0055\u0058\u004a\u0051\u0040\u0055\u0051\u004b\u0040\u006c\u005b\u0020\u006d\u0061\u0045\u0029\u0049\u0070\u0078\u0026\u0071\u0052\u0054\u004d\u0027\u0071\u0032\u0073\u0023\u0037\u0050\u004a\u0023\u0073\u0061\u0061\u0076\u002d\u006e\u0043\u0079\u002a\u0036\u003a\u0038\u0020\u0052\u0041\u006f\u0051\u0066\u002e\u003b\u0060\u007a\u006f\u0079\u0039\u006e\u0072\u0070\u0049\u0037\u0066\u004a\u0063\u005d\u0077\u0074\u0021\u0067\u0030\u007a\u005a\u007a\u0067\u0073\u0027\u007a\u0065\u0064\u0033\u0023\u007e\u0073\u004a\u003d\u0037\u0040\u0048\u007e\u0071\u0068\u0042\u0033\u0022\u007d\u0037\u002e\u0022\u0064\u0038\u0071\u007c\u005d\u0026\u0020\u005e\u002d\u0026\u004d\u007e\u005a\u007a\u0030\u004c\u0073\u0071\u007e\u0020\u003b\u0070\u002a\u0068\u006b\u002c\u0065\u002b\u0025\u0053\u0052\u0033\u0030\u0036\u002a\u0052\u004f\u002e\u0062\u0038\u004a\u004a\u0076\u0022\u005e\u0033\u0022\u0050\u004b\u0075\u005f\u007b\u002a\u004d\u0038\u0066\u0065\u006e\u003e\u003f\u0059\u003f\u0063\u0051\u0023\u004b\u0037\u002c\u0078\u0031\u002d\u0045\u006b\u002d\u005f\u002f\u004f\u002a\u0052\u0023\u005c\u0059\u004f\u0036\u0046\u0059\u002a\u0072\u007b\u0049\u007a\u0077\u0079\u0076\u0079\u003c\u0075\u003f\u0049\u0023\u0050\u0070\u002f\u0054\u0068\u002a\u0024\u0072\u0031\u003a\u0067\u0052\u003a\u003e\u0078\u0030\u0077\u0057\u0066\u0037\u0042\u0063\u0076\u0066\u007c\u0042\u0028\u0057\u0024\u0050\u0026\u0077\u004a\u0027\u0048\u006e\u0024\u0034\u0065\u004d\u004d\u002a\u0056\u0069\u0052\u003e\u0031\u007a\u0070\u0049\u0039\u0034\u0077\u0026\u0072\u0064\u0061\u0022\u0065\u0022\u0037\u002a\u006d\u003b\u003a\u0041\u0055\u007a\u0026\u0045\u0045\u0053\u005b\u0022\u005c\u0077\u004d\u0026\u004f\u005b\u003c\u0053\u0059\u0063\u0047\u0035\u005f\u0042\u0073\u0060\u0073\u002b\u002c\u0056\u0038\u0052\u004e\u0046\u003d\u0041\u0045\u0075\u003d\u007e\u005f\u004c\u0059\u0075\u0076\u002f\u0027\u0072\u0057\u0065\u0069\u0027\u0032\u0024\u0022\u0045\u002f\u0038\u003f\u0053\u002e\u005b\u0074\u002d\u0074\u0037\u0046\u005e\u003b\u0041\u007c\u0045\u0075\u004c\u0061\u0032\u002a\u0056\u004b\u004b\u0071\u005a\u007c\u0066\u007e\u0039\u0069\u0058\u0065\u006d\u007c\u0024\u0066\u0038\u002a\u0046\u0028\u0026\u006f\u0037\u0046\u002c\u004d\u0064\u0046\u006b\u0073\u0043\u0041\u0050\u0047\u0072\u0027\u0055\u005c\u0048\u0062\u006a\u003a\u006c\u0035\u0079\u0054\u0049\u0056\u004d\u0073\u0041\u0049\u0031\u0036\u004b\u0031\u0053\u006e\u006f\u0076\u006e\u006e\u004f\u003a\u0021\u006a\u0064\u003d\u005d\u005c\u005b\u006e\u0064\u003e\u0076\u006f\u0040\u0058\u006d\u0062\u004c\u0026\u0035\u0040\u007c\u002e\u0038\u006f\u0056\u002b\u003f\u0065\u0033\u0078\u0057\u0067\u003c\u0075\u0058\u002a\u0023\u0020\u002e\u0063\u0023\u0077\u0053\u0062\u0037\u002a\u003d\u0054\u0059\u0029\u006b\u0048\u0077\u0029\u0055\u006d\u0036\u0040\u0043\u0061\u0057\u0055\u002c\u0076\u0061\u0028\u007e\u0022\u004e\u0073\u004a\u0036\u0058\u0030\u0029\u0045\u004d\u0073\u0055\u0034\u0031\u007e\u0048\u0042\u0047\u0067\u007b\u0075\u0051\u0062\u003c\u005b\u0048\u0055\u0029\u007c\u0072\u002b\u003d\u002b\u0054\u007b\u0056\u0023\u0028\u0059\u0033\u0054\u0039\u0054\u004c\u006d\u0050\u0026\u0049\u0077\u0075\u005c\u0057\u0036\u0039\u0051\u0067\u0044\u002b\u0069\u007b\u0029\u003d\u004d\u0044\u006d\u0043\u003e\u0040\u007a\u002f\u002d\u0032\u0044\u0062\u0062\u007d\u0056\u0063\u007c